import { createAdminClient, getAdminKey, requireInternalSecret } from '../_shared/amazon/supabase.ts';
import { ensureAmazonAccountAndMarketplaces } from '../_shared/amazon/marketplaces.ts';
import { enqueueHourlySync, enqueueInitialBackfill } from '../_shared/amazon/sync.ts';
import { filterAutomaticMarketplaces, loadAmazonAutomaticSyncSettings } from '../_shared/amazon/settings.ts';

const jsonHeaders={'Content-Type':'application/json'};
function response(data:unknown,status=200){return new Response(JSON.stringify(data),{status,headers:jsonHeaders});}

async function requestAutomaticImageSync(ownerId:string,amazonAccountId:string){
  const url=(Deno.env.get('SUPABASE_URL')||'').trim();
  const key=getAdminKey();
  if(!url||!key)throw new Error('Configuración interna de Supabase no disponible para imágenes Amazon.');
  const result=await fetch(`${url.replace(/\/$/,'')}/functions/v1/amazon-sync-product-images`,{
    method:'POST',
    headers:{'Content-Type':'application/json','apikey':key},
    body:JSON.stringify({ownerId,amazonAccountId,limit:10}),
  });
  const payload=await result.json().catch(()=>({}));
  if(!result.ok||payload?.error)throw new Error(String(payload?.error||`Error HTTP ${result.status} sincronizando imágenes Amazon.`));
  return payload;
}

Deno.serve(async(req:Request)=>{
  if(req.method!=='POST')return response({error:'Método no permitido.'},405);
  try{
    requireInternalSecret(req);
    const admin=createAdminClient();
    const body=await req.json().catch(()=>({}));
    const mode=String(body?.mode||'hourly');
    const ordersOnly=body?.ordersOnly===true;
    if(!['initial','hourly','reconcile'].includes(mode))return response({error:'Modo de sincronización no válido.'},400);
    const {data:accounts,error:accountError}=await admin.from('amazon_accounts')
      .select('id,owner_id,integration_account_id').neq('status','disabled').order('updated_at',{ascending:false});
    if(accountError)throw accountError;
    let jobs=0;
    let processedAccounts=0;
    for(const configuredAccount of accounts||[]){
      const ownerId=String(configuredAccount.owner_id);
      const integrationAccountId=configuredAccount.integration_account_id?String(configuredAccount.integration_account_id):null;
      const bootstrap=await ensureAmazonAccountAndMarketplaces(admin,ownerId,integrationAccountId);
      const account=bootstrap.account;
      const automaticSettings=await loadAmazonAutomaticSyncSettings(admin,ownerId,integrationAccountId);
      if(!automaticSettings.automaticEnabled)continue;
      const marketplaces=filterAutomaticMarketplaces(bootstrap.marketplaces,automaticSettings.activeMarketplaceIds);
      const enabledSources=ordersOnly?automaticSettings.enabledSources.filter(source=>source==='orders'):automaticSettings.enabledSources;
      processedAccounts+=1;
      const started=new Date().toISOString();
      const {data:run,error:runError}=await admin.from('amazon_sync_runs').insert({owner_id:account.owner_id,amazon_account_id:account.id,source:'orchestrator',mode,status:'running',started_at:started}).select('id').single();
      if(runError)throw runError;
      try{
        let created:any[]=[];
        if(mode==='initial'){
          created=await enqueueInitialBackfill(admin,account,marketplaces,new Date(),enabledSources);
        }else if(mode==='hourly'){
          const {data:stateRows,error:stateError}=await admin.from('amazon_sync_state')
            .select('id')
            .eq('owner_id',account.owner_id)
            .eq('amazon_account_id',account.id)
            .limit(1);
          if(stateError)throw stateError;
          if(!ordersOnly&&!(stateRows||[]).length){
            const historical=await enqueueInitialBackfill(admin,account,marketplaces,new Date(),enabledSources);
            created.push(...historical);
          }
          const incremental=await enqueueHourlySync(admin,account,marketplaces,'hourly',new Date(),enabledSources);
          created.push(...incremental);
        }else{
          created=await enqueueHourlySync(admin,account,marketplaces,'reconcile',new Date(),enabledSources);
        }
        jobs+=created.length;
        let imageSync:Record<string,unknown>|null=null;
        let imageSyncError:string|null=null;
        if(!ordersOnly&&automaticSettings.autoSyncImages){
          try{imageSync=await requestAutomaticImageSync(ownerId,account.id);}
          catch(error){imageSyncError=error instanceof Error?error.message:'No se pudieron actualizar las imágenes Amazon.';}
        }
        await admin.from('amazon_sync_runs').update({
          status:'success',
          finished_at:new Date().toISOString(),
          rows_processed:created.length,
          checkpoint:{queued_jobs:created.length,image_sync:imageSync,image_sync_error:imageSyncError},
          updated_at:new Date().toISOString()
        }).eq('id',run.id);
      }catch(error){
        await admin.from('amazon_sync_runs').update({status:'failed',finished_at:new Date().toISOString(),error_message:error instanceof Error?error.message.slice(0,700):'Error de orquestación',updated_at:new Date().toISOString()}).eq('id',run.id);
        throw error;
      }
    }
    return response({ok:true,mode,accounts:processedAccounts,jobs});
  }catch(error){return response({error:error instanceof Error?error.message:'Error interno de sincronización.'},401);}
});

import { createClient } from 'npm:@supabase/supabase-js@2';

export type AppCaller={
  user_id:string;
  data_owner_id:string;
  role:string;
  active:boolean;
  permissions:string[]|null;
};

export function getAdminKey(){
  const secretKeys=Deno.env.get('SUPABASE_SECRET_KEYS');
  if(secretKeys){
    try{
      const parsed=JSON.parse(secretKeys);
      if(typeof parsed?.default==='string'&&parsed.default.trim())return parsed.default.trim();
    }catch{/* legacy fallback below */}
  }
  return (Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')||'').trim();
}

export function createAdminClient(){
  const url=(Deno.env.get('SUPABASE_URL')||'').trim();
  const key=getAdminKey();
  if(!url||!key)throw new Error('Configuración interna de Supabase no disponible.');
  return createClient(url,key,{auth:{persistSession:false,autoRefreshToken:false}});
}

export function requireInternalSecret(req:Request){
  const expected=getAdminKey();
  const presented=(req.headers.get('apikey')||'').trim();
  if(!expected||!presented||presented!==expected)throw new Error('Llamada interna no autorizada.');
}

export async function authenticateUser(req:Request,admin:any):Promise<AppCaller>{
  const token=(req.headers.get('Authorization')||'').replace(/^Bearer\s+/i,'').trim();
  if(!token)throw new Error('Sesión no válida.');
  const {data:userData,error:userError}=await admin.auth.getUser(token);
  if(userError||!userData?.user)throw new Error('Sesión no válida.');
  const {data:caller,error}=await admin.from('app_users')
    .select('user_id,data_owner_id,role,active,permissions')
    .eq('user_id',userData.user.id)
    .maybeSingle();
  if(error)throw error;
  if(!caller?.active)throw new Error('Tu acceso está desactivado.');
  const {data:workspace,error:workspaceError}=await admin.from('workspaces').select('status').eq('id',caller.data_owner_id).maybeSingle();
  if(workspaceError)throw workspaceError;
  if(!workspace||!['active','trialing'].includes(workspace.status))throw new Error('El acceso de tu empresa está suspendido.');
  return caller as AppCaller;
}

export async function authenticateAdminUser(req:Request,admin:any){
  const caller=await authenticateUser(req,admin);
  if(caller.role!=='admin')throw new Error('Solo un administrador puede iniciar una sincronización manual de Amazon.');
  return caller;
}

import { loadAmazonSpApiCredentials } from './config.ts';
import { spApiRequest } from './sp-api.ts';

const EUROPE_COUNTRY_CODES=new Set(['BE','DE','ES','FR','GB','IE','IT','NL','PL','SE']);

type MarketplaceParticipation={
  marketplace?:{id?:string;name?:string;countryCode?:string;defaultCurrencyCode?:string};
  storeName?:string;
  participation?:{isParticipating?:boolean;hasSuspendedListings?:boolean};
};

type MarketplaceResponse={payload?:MarketplaceParticipation[]};

async function resolveIntegrationAccount(admin:any,ownerId:string,sellerId:string,preferredId?:string|null){
  if(preferredId){
    const {data,error}=await admin.from('integration_accounts')
      .select('id,display_name,status,enabled')
      .eq('owner_id',ownerId).eq('provider','amazon').eq('id',preferredId).maybeSingle();
    if(error)throw error;
    if(!data)throw new Error('La cuenta de integración Amazon no existe.');
    return data;
  }
  const {data,error}=await admin.from('integration_accounts')
    .select('id,display_name,status,enabled')
    .eq('owner_id',ownerId).eq('provider','amazon').eq('external_account_id',sellerId).maybeSingle();
  if(error)throw error;
  return data||null;
}

export async function ensureAmazonAccountAndMarketplaces(admin:any,ownerId:string,integrationAccountId?:string|null){
  const credentials=await loadAmazonSpApiCredentials(admin,{integrationAccountId,ownerId});
  const integration=await resolveIntegrationAccount(admin,ownerId,credentials.sellerId,integrationAccountId);
  if(integration&&(integration.status==='disabled'||integration.enabled===false))throw new Error('La cuenta de Amazon está deshabilitada.');
  const now=new Date().toISOString();
  const displayAlias=String(integration?.display_name||'Amazon Europe');
  const {data:account,error:accountError}=await admin.from('amazon_accounts').upsert({
    owner_id:ownerId,
    seller_id:credentials.sellerId,
    display_name:displayAlias,
    region:'EU',
    status:'pending',
    integration_account_id:integration?.id||null,
    updated_at:now,
  },{onConflict:'owner_id,seller_id'}).select('id,owner_id,seller_id,display_name,status,initial_sync_from,last_successful_sync_at,integration_account_id').single();
  if(accountError)throw accountError;

  if(integration){
    const link=await admin.from('integration_accounts').update({linked_resource_id:account.id,updated_at:now})
      .eq('id',integration.id).eq('owner_id',ownerId);
    if(link.error)throw link.error;
  }

  try{
    const result=await spApiRequest<MarketplaceResponse>('/sellers/v1/marketplaceParticipations',{},credentials);
    const participations=(result?.payload||[]).filter(item=>{
      const marketplace=item?.marketplace;
      const marketplaceName=String(marketplace?.name||'').trim();
      return Boolean(
        marketplace?.id&&
        marketplace?.countryCode&&
        EUROPE_COUNTRY_CODES.has(String(marketplace.countryCode).toUpperCase())&&
        marketplaceName.startsWith('Amazon.')
      );
    });

    const inactive=await admin.from('amazon_marketplaces').update({active:false,updated_at:now})
      .eq('owner_id',ownerId).eq('amazon_account_id',account.id);
    if(inactive.error)throw inactive.error;

    const rows=participations.map(item=>{
      const marketplace=item.marketplace!;
      return {
        owner_id:ownerId,
        amazon_account_id:account.id,
        marketplace_id:String(marketplace.id),
        country_code:String(marketplace.countryCode||'').toUpperCase(),
        name:String(marketplace.name||marketplace.countryCode||marketplace.id),
        currency_code:String(marketplace.defaultCurrencyCode||'EUR').toUpperCase(),
        active:Boolean(item.participation?.isParticipating),
        updated_at:now,
      };
    });

    if(rows.length){
      const {error:marketError}=await admin.from('amazon_marketplaces').upsert(rows,{onConflict:'owner_id,amazon_account_id,marketplace_id'});
      if(marketError)throw marketError;
    }

    const remoteName=participations.find(item=>item.storeName)?.storeName;
    const displayName=integration?.display_name||remoteName||displayAlias;
    const {error:statusError}=await admin.from('amazon_accounts').update({display_name:displayName,status:'connected',integration_account_id:integration?.id||null,updated_at:now}).eq('id',account.id).eq('owner_id',ownerId);
    if(statusError)throw statusError;
    if(integration){
      const {error:integrationError}=await admin.from('integration_accounts').update({
        status:'connected',linked_resource_id:account.id,last_tested_at:now,last_success_at:now,last_error:null,updated_at:now,
      }).eq('id',integration.id).eq('owner_id',ownerId);
      if(integrationError)throw integrationError;
    }

    const {data:marketplaces,error:listError}=await admin.from('amazon_marketplaces')
      .select('marketplace_id,country_code,name,currency_code,active')
      .eq('owner_id',ownerId).eq('amazon_account_id',account.id).eq('active',true)
      .order('country_code',{ascending:true});
    if(listError)throw listError;

    return {account:{...account,display_name:displayName,status:'connected',integration_account_id:integration?.id||null},marketplaces:marketplaces||[]};
  }catch(error){
    const message=error instanceof Error?error.message:'No se pudo comprobar Amazon.';
    await admin.from('amazon_accounts').update({status:'error',updated_at:new Date().toISOString()}).eq('id',account.id).eq('owner_id',ownerId);
    if(integration)await admin.from('integration_accounts').update({status:'error',last_tested_at:new Date().toISOString(),last_error:message.slice(0,700),updated_at:new Date().toISOString()}).eq('id',integration.id).eq('owner_id',ownerId);
    throw error;
  }
}

export type AmazonSpApiCredentials={
  clientId:string;
  clientSecret:string;
  refreshToken:string;
  sellerId:string;
};

function clean(value:unknown){return String(value??'').trim();}
function required(value:unknown,name:string){
  const text=clean(value);
  if(!text)throw new Error(`Falta ${name} en la configuración de Amazon SP-API.`);
  return text;
}
function parseEnv(){
  const raw=clean(Deno.env.get('AMAZON_SPAPI_CREDENTIALS'));
  if(!raw)return {} as any;
  try{return JSON.parse(raw)}catch{throw new Error('AMAZON_SPAPI_CREDENTIALS no contiene JSON válido.');}
}
function normalize(stored:any,env:any,fallbackSellerId=''):AmazonSpApiCredentials{
  const refreshToken=clean(stored?.refreshToken)||clean(stored?.refresh_token);
  if(!refreshToken)throw new Error('cuenta Amazon sin credenciales');
  return {
    // SP-API/LWA app credentials can be shared by every tenant using the same
    // registered application. Seller-specific credentials cannot.
    clientId:required(stored?.clientId||stored?.client_id||env?.clientId||env?.client_id,'client_id'),
    clientSecret:required(stored?.clientSecret||stored?.client_secret||env?.clientSecret||env?.client_secret,'client_secret'),
    refreshToken:refreshToken,
    sellerId:required(stored?.sellerId||stored?.seller_id||fallbackSellerId,'seller_id'),
  };
}

export function readAmazonSpApiCredentials():AmazonSpApiCredentials{
  throw new Error('cuenta Amazon sin credenciales');
}

async function readIntegrationSecret(admin:any,integrationAccountId:string,ownerId?:string|null){
  let query=admin.from('integration_accounts')
    .select('id,owner_id,external_account_id,secret_id,credential_source,status,enabled')
    .eq('id',integrationAccountId).eq('provider','amazon');
  if(ownerId)query=query.eq('owner_id',ownerId);
  const {data:integration,error}=await query.maybeSingle();
  if(error)throw error;
  if(!integration)throw new Error('La cuenta de integración de Amazon no existe.');
  if(integration.status==='disabled'||integration.enabled===false)throw new Error('La cuenta de Amazon está deshabilitada.');
  let stored:any={};
  if(integration.secret_id){
    const {data:secret,error:secretError}=await admin.rpc('integration_read_secret',{p_secret_id:integration.secret_id});
    if(secretError)throw secretError;
    try{stored=JSON.parse(String(secret||'{}'))}catch{throw new Error('Las credenciales cifradas de Amazon no tienen un formato válido.');}
  }
  return {integration,stored};
}

export async function loadAmazonSpApiCredentials(
  admin:any,
  options:{amazonAccountId?:string|null;integrationAccountId?:string|null;ownerId?:string|null}={},
):Promise<AmazonSpApiCredentials>{
  const env=parseEnv();
  const ownerId=clean(options.ownerId);
  let integrationAccountId=clean(options.integrationAccountId);
  let fallbackSellerId='';
  let accountOwnerId=ownerId;

  if(options.amazonAccountId){
    let accountQuery=admin.from('amazon_accounts')
      .select('seller_id,integration_account_id,owner_id')
      .eq('id',options.amazonAccountId);
    if(ownerId)accountQuery=accountQuery.eq('owner_id',ownerId);
    const {data:account,error}=await accountQuery.maybeSingle();
    if(error)throw error;
    if(!account)throw new Error('La cuenta Amazon asociada al trabajo ya no existe.');
    if(integrationAccountId&&integrationAccountId!==clean(account.integration_account_id)){
      throw new Error('La cuenta de integración no corresponde al trabajo de Amazon.');
    }
    accountOwnerId=clean(account.owner_id);
    fallbackSellerId=clean(account.seller_id);
    integrationAccountId=integrationAccountId||clean(account.integration_account_id);
  }

  if(!integrationAccountId){
    throw new Error('Amazon SP-API no está configurado para este workspace.');
  }

  const {integration,stored}=await readIntegrationSecret(admin,integrationAccountId,accountOwnerId||null);
  const ownToken=clean(stored?.refreshToken)||clean(stored?.refresh_token);
  if(!ownToken){
    // This allowlist contains integration_accounts.id, never a seller ID or a
    // caller-supplied workspace. The row above has already been owner-checked.
    const allowedId=clean(Deno.env.get('AMAZON_LEGACY_FALLBACK_ACCOUNT_ID'));
    const legacyToken=clean(env?.refreshToken)||clean(env?.refresh_token);
    if(!allowedId||clean(integration.id)!==allowedId||!legacyToken){
      throw new Error('cuenta Amazon sin credenciales');
    }
    const credentials=normalize({refreshToken:legacyToken},env,clean(integration.external_account_id)||fallbackSellerId);
    console.warn('amazon_legacy_fallback_used',{integration_account_id:integration.id,owner_id:integration.owner_id});
    return credentials;
  }
  return normalize(stored,env,clean(integration.external_account_id)||fallbackSellerId);
}

import { readAmazonSpApiCredentials, type AmazonSpApiCredentials } from './config.ts';
import { retryAfterMs, sanitizeAmazonError, sleep } from './http.ts';

const LWA_URL='https://api.amazon.com/auth/o2/token';
export const SP_API_BASE='https://sellingpartnerapi-eu.amazon.com';
export const MAX_ATTEMPTS=4;
const USER_AGENT='ZENVIA-Gestion/1.0 (Language=TypeScript; Platform=Supabase-Edge)';

type TokenCache={token:string;expiresAt:number};
const tokenCache=new Map<string,TokenCache>();

function amazonDate(date=new Date()){
  return date.toISOString().replace(/[:-]|\.\d{3}/g,'');
}

export async function getLwaAccessToken(credentials:AmazonSpApiCredentials=readAmazonSpApiCredentials()){
  const now=Date.now();
  const cacheKey=`${credentials.sellerId}:${credentials.clientId}:${credentials.refreshToken.slice(-12)}`;
  const cachedToken=tokenCache.get(cacheKey);
  if(cachedToken&&cachedToken.expiresAt>now+60_000)return cachedToken.token;
  const body=new URLSearchParams();
  body.set('grant_type','refresh_token');
  body.set('refresh_token',credentials.refreshToken);
  body.set('client_id',credentials.clientId);
  body.set('client_secret',credentials.clientSecret);
  const response=await fetch(LWA_URL,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body});
  const text=await response.text();
  let data:any=null;try{data=text?JSON.parse(text):null}catch{data=null}
  if(!response.ok||!data?.access_token){
    throw new Error(`Amazon LWA (${response.status}): ${sanitizeAmazonError(data?.error_description||data?.error||text)}`);
  }
  const expiresIn=Math.max(60,Number(data.expires_in)||3600);
  const next={token:String(data.access_token),expiresAt:now+(expiresIn*1000)};
  tokenCache.set(cacheKey,next);
  return next.token;
}

export type SpApiRequestOptions={
  method?:'GET'|'POST'|'PUT'|'DELETE';
  query?:Record<string,string|number|boolean|Array<string|number>|null|undefined>;
  body?:unknown;
  maxAttempts?:number;
};

function buildUrl(path:string,query?:SpApiRequestOptions['query']){
  const url=new URL(path.startsWith('http')?path:`${SP_API_BASE}${path.startsWith('/')?'':'/'}${path}`);
  for(const [key,value] of Object.entries(query||{})){
    if(value==null)continue;
    if(Array.isArray(value))url.searchParams.set(key,value.map(String).join(','));
    else url.searchParams.set(key,String(value));
  }
  return url;
}

function transient(status:number){return [429,500,502,503,504].includes(status);}

export async function spApiRequest<T=any>(path:string,options:SpApiRequestOptions={},credentials?:AmazonSpApiCredentials):Promise<T>{
  const url=buildUrl(path,options.query);
  for(let attempt=0;attempt<(options.maxAttempts||MAX_ATTEMPTS);attempt+=1){
    const accessToken=await getLwaAccessToken(credentials);
    const headers=new Headers({
      Accept:'application/json',
      'user-agent':USER_AGENT,
      'x-amz-access-token':accessToken,
      'x-amz-date':amazonDate(),
    });
    let body:BodyInit|undefined;
    if(options.body!==undefined){headers.set('Content-Type','application/json');body=JSON.stringify(options.body);}
    const response=await fetch(url,{method:options.method||'GET',headers,body,signal:AbortSignal.timeout(25000)});
    const text=await response.text();
    if(response.ok){
      if(!text)return undefined as T;
      try{return JSON.parse(text) as T}catch{throw new Error('Amazon SP-API devolvió una respuesta JSON no válida.');}
    }
    if(transient(response.status)&&attempt<(options.maxAttempts||MAX_ATTEMPTS)-1){
      await sleep(retryAfterMs(response.headers,attempt));
      continue;
    }
    let parsed:any=null;try{parsed=text?JSON.parse(text):null}catch{/* keep raw */}
    const detail=parsed?.errors?.map?.((item:any)=>item?.message||item?.code).filter(Boolean).join(' · ')||parsed?.message||text;
    throw new Error(`Amazon SP-API (${response.status}): ${sanitizeAmazonError(detail)}`);
  }
  throw new Error('Amazon SP-API agotó los reintentos.');
}

export function sanitizeAmazonError(value:unknown){
  const message=value instanceof Error?value.message:
    typeof value==='string'?value:
    value&&typeof value==='object'?(
      [((value as Record<string,unknown>).message),((value as Record<string,unknown>).details),((value as Record<string,unknown>).hint),((value as Record<string,unknown>).code)]
        .filter(part=>typeof part==='string'&&part.length>0).join(' | ')||JSON.stringify(value)
    ):String(value??'Error desconocido');
  return message
    .replace(/Atz[ar]\|[A-Za-z0-9._|\-]+/g,'[redacted-token]')
    .replace(/("?(?:client_secret|refresh_token|access_token)"?\s*[:=]\s*")([^"]+)(")/gi,'$1[redacted]$3')
    .slice(0,700);
}

export function sleep(ms:number){
  return new Promise<void>(resolve=>setTimeout(resolve,ms));
}

export function retryAfterMs(headers:Headers,attempt:number){
  const raw=headers.get('retry-after');
  const seconds=raw==null?NaN:Number(raw);
  if(Number.isFinite(seconds)&&seconds>=0)return Math.min(10_000,Math.max(100,seconds*1000));
  return Math.min(8_000,500*(2**attempt));
}

import { sanitizeAmazonError } from './http.ts';

export const INITIAL_SYNC_FROM='2026-01-01T00:00:00Z';
export const BACKFILL_WINDOW_DAYS=7;
export const OVERLAP_HOURS=6;
export const CURRENT_SYNC_MAX_LOOKBACK_HOURS=7*24;

type Mode='initial'|'hourly'|'manual'|'reconcile';
export type AmazonSyncSource='orders'|'finances'|'inventory';
type Source=AmazonSyncSource;
const ALL_SYNC_SOURCES:AmazonSyncSource[]=['orders','finances','inventory'];
function enabledSourceSet(enabledSources?:AmazonSyncSource[]){return new Set(enabledSources===undefined?ALL_SYNC_SOURCES:enabledSources);}
type Account={id:string;owner_id:string;initial_sync_from?:string|null};
type Marketplace={marketplace_id:string;active?:boolean};

function iso(value:Date|string){return new Date(value).toISOString();}
function plusDays(value:Date,days:number){const next=new Date(value);next.setUTCDate(next.getUTCDate()+days);return next;}
function minusHours(value:Date,hours:number){const next=new Date(value);next.setUTCHours(next.getUTCHours()-hours);return next;}
function hourKey(value:Date){const d=new Date(value);d.setUTCMinutes(0,0,0);return d.toISOString();}

function jobKey(source:Source,marketplaceId:string|null,from:string|null,to:string|null,mode:Mode){
  return [mode,source,marketplaceId||'global',from||'current',to||'current'].join(':');
}

async function insertJobs(admin:any,rows:any[]){
  for(let offset=0;offset<rows.length;offset+=200){
    const batch=rows.slice(offset,offset+200);
    const {error}=await admin.from('amazon_sync_jobs').upsert(batch,{onConflict:'owner_id,amazon_account_id,job_key',ignoreDuplicates:true});
    if(error)throw error;
  }
  return rows.length;
}

export async function enqueueInitialBackfill(admin:any,account:Account,marketplaces:Marketplace[],until=new Date(),enabledSources?:AmazonSyncSource[]){
  const start=new Date(account.initial_sync_from||INITIAL_SYNC_FROM);
  const end=new Date(until);
  const rows:any[]=[];
  const enabled=enabledSourceSet(enabledSources);
  for(const marketplace of marketplaces.filter(item=>item.active!==false)){
    let cursor=new Date(start);
    while(cursor<end){
      const windowEnd=plusDays(cursor,BACKFILL_WINDOW_DAYS);
      const clipped=windowEnd>end?end:windowEnd;
      for(const source of ['orders','finances'] as const){
        if(!enabled.has(source))continue;
        const from=iso(cursor),to=iso(clipped);
        rows.push({owner_id:account.owner_id,amazon_account_id:account.id,job_key:jobKey(source,marketplace.marketplace_id,from,to,'initial'),source,marketplace_id:marketplace.marketplace_id,scope_key:marketplace.marketplace_id,window_from:from,window_to:to,status:'queued',attempts:0,max_attempts:5,available_at:new Date().toISOString(),payload:{mode:'initial'}});
      }
      cursor=clipped;
    }
    if(enabled.has('inventory'))rows.push({owner_id:account.owner_id,amazon_account_id:account.id,job_key:jobKey('inventory',marketplace.marketplace_id,null,hourKey(end),'initial'),source:'inventory',marketplace_id:marketplace.marketplace_id,scope_key:marketplace.marketplace_id,status:'queued',attempts:0,max_attempts:5,available_at:new Date().toISOString(),payload:{mode:'initial',snapshot:'current'}});
  }
  await insertJobs(admin,rows);
  return rows;
}

export async function enqueueHourlySync(admin:any,account:Account,marketplaces:Marketplace[],mode:Extract<Mode,'hourly'|'manual'|'reconcile'>='hourly',now=new Date(),enabledSources?:AmazonSyncSource[]){
  const ids=marketplaces.filter(item=>item.active!==false).map(item=>item.marketplace_id);
  const enabled=enabledSourceSet(enabledSources);
  const {data:states,error}=await admin.from('amazon_sync_state')
    .select('source,scope_key,marketplace_id,high_water_mark')
    .eq('owner_id',account.owner_id)
    .eq('amazon_account_id',account.id);
  if(error)throw error;
  const stateMap=new Map((states||[]).map((state:any)=>[`${state.source}:${state.scope_key}`,state]));
  const rows:any[]=[];
  for(const marketplaceId of ids){
    for(const source of ['orders','finances'] as const){
      if(!enabled.has(source))continue;
      const state:any=stateMap.get(`${source}:${marketplaceId}`);
      const baseline=state?.high_water_mark?new Date(state.high_water_mark):minusHours(now,OVERLAP_HOURS);
      // Finance movements may be published late with an older posting timestamp.
      // Replay a wider window; transaction keys and atomic upserts are idempotent.
      const overlapStart=minusHours(baseline,source==='finances'?24:OVERLAP_HOURS);
      const freshnessFloor=minusHours(now,CURRENT_SYNC_MAX_LOOKBACK_HOURS);
      const boundedStart=overlapStart<freshnessFloor?freshnessFloor:overlapStart;
      const from=iso(boundedStart),to=iso(now);
      rows.push({owner_id:account.owner_id,amazon_account_id:account.id,job_key:jobKey(source,marketplaceId,from,to,mode),source,marketplace_id:marketplaceId,scope_key:marketplaceId,window_from:from,window_to:to,status:'queued',attempts:0,max_attempts:5,available_at:new Date().toISOString(),payload:{mode,high_water_mark:state?.high_water_mark||null}});
    }
    if(enabled.has('inventory'))rows.push({owner_id:account.owner_id,amazon_account_id:account.id,job_key:jobKey('inventory',marketplaceId,null,hourKey(now),mode),source:'inventory',marketplace_id:marketplaceId,scope_key:marketplaceId,status:'queued',attempts:0,max_attempts:5,available_at:new Date().toISOString(),payload:{mode,snapshot:'current'}});
  }
  await insertJobs(admin,rows);
  return rows;
}

export async function markJobSuccess(admin:any,job:any,rowsProcessed:number){
  const finished=new Date().toISOString();
  const durationMs=job.started_at?Math.max(0,Date.now()-new Date(job.started_at).getTime()):null;
  const {data:completed,error}=await admin.from('amazon_sync_jobs').update({status:'success',rows_processed:rowsProcessed,finished_at:finished,locked_at:null,last_error:null,updated_at:finished,duration_ms:durationMs,lease_holder_id:null}).eq('id',job.id).eq('status','running').eq('lease_holder_id',job.lease_holder_id).select('id');
  if(error)throw error;
  if(!completed?.length)throw new Error('Job lease ownership lost before success update');

  const scopeKey=job.scope_key||job.marketplace_id||'global';
  const candidateHighWater=new Date(job.window_to||finished);
  const {data:existingState,error:existingStateError}=await admin.from('amazon_sync_state')
    .select('high_water_mark')
    .eq('owner_id',job.owner_id)
    .eq('amazon_account_id',job.amazon_account_id)
    .eq('source',job.source)
    .eq('scope_key',scopeKey)
    .maybeSingle();
  if(existingStateError)throw existingStateError;

  let highWater=candidateHighWater.toISOString();
  if(existingState?.high_water_mark){
    const currentHighWater=new Date(existingState.high_water_mark);
    if(!Number.isNaN(currentHighWater.getTime())&&currentHighWater>candidateHighWater){
      highWater=currentHighWater.toISOString();
    }
  }

  const {error:stateError}=await admin.from('amazon_sync_state').upsert({owner_id:job.owner_id,amazon_account_id:job.amazon_account_id,source:job.source,scope_key:scopeKey,marketplace_id:job.marketplace_id||null,high_water_mark:highWater,last_successful_at:finished,checkpoint:{last_job_id:job.id,rows_processed:rowsProcessed},updated_at:finished},{onConflict:'owner_id,amazon_account_id,source,scope_key'});
  if(stateError)throw stateError;

  const {error:accountError}=await admin.from('amazon_accounts').update({last_successful_sync_at:finished,updated_at:finished})
    .eq('id',job.amazon_account_id)
    .eq('owner_id',job.owner_id);
  if(accountError)throw accountError;
}

export async function markJobFailed(admin:any,job:any,errorValue:unknown){
  const attempts=Number(job.attempts)||1,maxAttempts=Number(job.max_attempts)||5;
  const terminal=attempts>=maxAttempts;
  const delaySeconds=Math.min(3600,Math.max(60,60*(2**Math.max(0,attempts-1))));
  const availableAt=new Date(Date.now()+delaySeconds*1000).toISOString();
  const errorMessage=sanitizeAmazonError(errorValue instanceof Error?errorValue.message:errorValue);
  const durationMs=job.started_at?Math.max(0,Date.now()-new Date(job.started_at).getTime()):null;
  const {data:updated,error}=await admin.from('amazon_sync_jobs').update({status:terminal?'failed':'queued',available_at:availableAt,locked_at:null,lease_holder_id:null,finished_at:terminal?new Date().toISOString():null,last_error:errorMessage,updated_at:new Date().toISOString(),attempts,duration_ms:durationMs}).eq('id',job.id).eq('status','running').eq('lease_holder_id',job.lease_holder_id).select('id');
  if(error)throw error;
  if(!updated?.length)throw new Error('Job lease ownership lost before failure update');
}

export type AmazonAutomaticSyncSettings={
  automaticEnabled:boolean;
  activeMarketplaceIds:string[];
  enabledSources:Array<'orders'|'finances'|'inventory'>;
  autoSyncImages:boolean;
};

function bool(value:unknown,fallback=true){return typeof value==='boolean'?value:fallback;}
function strings(value:unknown){
  if(!Array.isArray(value))return [];
  return Array.from(new Set(value.map(item=>String(item||'').trim()).filter(Boolean)));
}

export async function loadAmazonAutomaticSyncSettings(admin:any,ownerId:string,integrationAccountId?:string|null):Promise<AmazonAutomaticSyncSettings>{
  const {data,error}=await admin.from('app_settings').select('config').eq('owner_id',ownerId).maybeSingle();
  if(error)throw error;

  const root=(data?.config&&typeof data.config==='object'&&!Array.isArray(data.config))?(data.config as any):{};
  const amazon=root.amazon;
  const global=amazon&&typeof amazon==='object'&&!Array.isArray(amazon)?amazon:{};

  let accountConfig:any={};
  let accountEnabled=true;
  if(integrationAccountId){
    const {data:account,error:accountError}=await admin.from('integration_accounts')
      .select('config,enabled,status').eq('owner_id',ownerId).eq('id',integrationAccountId).eq('provider','amazon').maybeSingle();
    if(accountError)throw accountError;
    if(account){
      accountConfig=account.config&&typeof account.config==='object'&&!Array.isArray(account.config)?account.config:{};
      accountEnabled=account.enabled!==false&&account.status!=='disabled';
    }
  }

  const enabledSources:Array<'orders'|'finances'|'inventory'>=[];
  if(bool(accountConfig.syncOrders,bool(global.autoSyncOrders,true)))enabledSources.push('orders');
  if(bool(accountConfig.syncFinance,bool(global.autoSyncFinance,true)))enabledSources.push('finances');
  if(bool(accountConfig.syncInventory,bool(global.autoSyncInventory,true)))enabledSources.push('inventory');

  const globalEnabled=bool(root?.integrations?.amazonEnabled,true);
  const automaticEnabled=globalEnabled&&accountEnabled;
  const accountMarketplaces=strings(accountConfig.activeMarketplaceIds);
  return {
    automaticEnabled,
    activeMarketplaceIds:accountMarketplaces.length?accountMarketplaces:strings(global.activeMarketplaceIds),
    // Keep source preferences available to explicit/manual sync. Automatic callers
    // already gate execution with automaticEnabled before using these sources.
    enabledSources,
    autoSyncImages:automaticEnabled&&bool(accountConfig.syncImages,bool(global.autoSyncImages,true)),
  };
}

export function filterAutomaticMarketplaces<T extends {marketplace_id:string;active?:boolean}>(
  marketplaces:T[],
  activeMarketplaceIds:string[],
){
  const available=marketplaces.filter(item=>item.active!==false);
  if(!activeMarketplaceIds.length)return available;
  const configured=new Set(activeMarketplaceIds);
  const filtered=available.filter(item=>configured.has(String(item.marketplace_id)));
  return filtered.length?filtered:available;
}
